const p=pages[document.body.dataset.page];const controls='<span class="palette" aria-label="Відтінки сиреневого"><button class="swatch active" data-tone="lavender" aria-label="Lavender"></button><button class="swatch" data-tone="orchid" aria-label="Orchid"></button><button class="swatch" data-tone="plum" aria-label="Plum"></button></span>';const nav='<header class="nav"><a class="brand" href=""><img src="https://www.uniks.com.ua/wp-content/uploads/2020/04/uniks-logo2.png.webp" alt="UNIKS"></a><nav class="navlinks"><a href="about/">Про UNIKS</a><a href="brands/">Власні бренди</a><a href="rnd/">Лабораторія R&amp;D</a><a href="private-label/">Контрактне виробництво</a><a href="certification/">Сертифікація</a><a href="partnerships/">Партнерства</a><a href="news/">Новини та події</a><a href="contact/">Контакти</a></nav><button class="locale" type="button">UA / EN</button>'+controls+'</header>';
document.body.innerHTML=nav+`<main><section class="hero"><div class="orb"></div><div class="orb rose"></div><div><div class="eyebrow">${p.k}</div><h1>${p.t}</h1><p class="lead">${p.lead}</p></div><a class="cta" href="#details">Дізнатися більше <b>↘</b></a></section><section id="details" class="intro reveal"><div class="section-title">${p.introLabel||'UNIKS / '+p.k}</div><div><h2>${p.h}</h2><div class="cards">${p.cards.map(x=>`<article class="card"><i>${x[0]}</i><div><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join('')}</div></div></section>${p.privateLabel?`<section class="project-ready reveal"><div class="section-title">Що корисно підготувати</div><div><h2>Не потрібен готовий<br><em>технічний бриф.</em></h2><p>Достатньо розповісти, яку задачу має вирішити продукт. Якщо вже є референси, бажаний формат, ринок або орієнтир по ціні — візьмемо це за точку старту.</p><div class="ready-list"><span>Ідея або категорія</span><span>Цільовий ринок</span><span>Референси, якщо є</span><span>Бажаний термін запуску</span></div></div></section>`:''}${p.rnd?`<section class="lab-note reveal"><div class="section-title">Підхід R&D</div><div><h2>Те, що не видно<br><em>на етикетці.</em></h2><p>Відчуття після нанесення, поведінка текстури, аромат у ритуалі, поєднання з пакуванням — ці деталі і формують любов до продукту. Ми тримаємо їх у фокусі ще до запуску.</p><div class="lab-terms"><span>Текстура</span><span>Аромат</span><span>Сенсорика</span><span>Стабільність</span></div></div></section>`:''}${p.manufacturing?`<section class="quality-grid reveal"><div class="section-title">Система якості</div><div><h2>Стабільність —<br><em>видима в деталях.</em></h2><p>Ми не маскуємо виробництво за красивими словами. Прозора послідовність рішень і контрольних точок створює продукт, якому можна довіряти.</p><div class="quality-points"><span>01 / Матеріали</span><span>02 / Процес</span><span>03 / Параметри</span><span>04 / Готова партія</span></div></div></section>`:''}<section class="band reveal"><div class="section-title">Як це працює</div><h2>Від першої думки<br>до спільного результату.</h2><div class="stages">${p.steps.map((x,i)=>`<div class="stage"><span>0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section><section class="next"><div><div class="section-title">Наступна сторінка</div><h2>${p.next}</h2><p>Продовжіть знайомство з підходом UNIKS або одразу почніть розмову про свій продукт.</p></div><a class="cta" href="${p.link}">Перейти <b>↗</b></a></section></main><footer class="footer"><span>© UNIKS / DEMO</span><span>PRIVATE LABEL · R&amp;D · MANUFACTURING</span><span>UA / EN</span></footer>`;
const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}),{threshold:.1});document.querySelectorAll('.reveal').forEach(x=>o.observe(x));const tones={lavender:['#21172d','#fbf8fc','#d8b7f0','#cb6ce8'],orchid:['#231b30','#fcf9fd','#d4b3e8','#9e71c0'],plum:['#1b1126','#fbf8fc','#ba92d8','#673e80']};document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>{let t=tones[b.dataset.tone],r=document.documentElement.style;r.setProperty('--ink',t[0]);r.setProperty('--paper',t[1]);r.setProperty('--lime',t[2]);r.setProperty('--rose',t[3]);document.querySelectorAll('.swatch').forEach(x=>x.classList.toggle('active',x===b))});
if(document.body.dataset.page==='partnerships'){const block=document.createElement('section');block.className='partner-wall reveal';block.innerHTML='<div class="section-title">Середовище довіри</div><div><h2>Партнерства, що<br><em>видно на полиці.</em></h2><p>UNIKS працює з роздрібними мережами, професійними каналами та командами, для яких важливі якість продукту, ясність процесу й довга дистанція.</p><div class="partner-logos" aria-label="Партнери UNIKS"><span>NOVUS</span><span>EVA</span><span>Епіцентр</span><span>BROCARD</span><span>Медтехніка</span><span>SHIK</span><span>MAKEUP</span></div></div>';document.querySelector('.band').before(block);o.observe(block)}
