if(document.body.dataset.page==='private-label'){const band=document.querySelector('.band');const proof=document.createElement('section');proof.className='pl-proof reveal';proof.innerHTML='<div class="section-title">Досвід UNIKS</div><div><h2>Менше ризиків.<br><em>Більше готовності</em> до запуску.</h2><p>Контрактне виробництво повного циклу: від ідеї, формули та сировини до виробництва, фасування і готового продукту під вашою торговою маркою.</p><div class="pl-numbers"><div><b>25</b><span>років на ринку</span></div><div><b>500+</b><span>клієнтів</span></div><div><b>1500+</b><span>реалізованих формул</span></div></div></div>';const categories=document.createElement('section');categories.className='pl-categories reveal';categories.innerHTML='<div class="section-title">Портфель формул</div><h2>Зберіть власну<br><em>лінійку.</em></h2><div class="category-grid"><article><h3>Обличчя</h3><p>Тонізація, очищення, креми, сироватки, маски та скраби.</p></article><article><h3>Тіло</h3><p>Скраби, лосьйони, батери, гелі й олії для душу, рідке мило.</p></article><article><h3>Волосся</h3><p>Шампуні, маски, кондиціонери, спреї та флюїди.</p></article><article><h3>Дім</h3><p>Засоби для прання, прибирання та ароматизації приміщень.</p></article><article><h3>Ванна</h3><p>Бомбочки, солі та бісер для ванної.</p></article><article><h3>Baby 0+ / Kids 3+</h3><p>Засоби для купання, догляду та дитячі продукти.</p></article></div>';const ready=document.querySelector('.project-ready');band.before(proof,categories,ready);[proof,categories].forEach(x=>o.observe(x))}
