if(document.body.dataset.page==='about'){const awards=document.createElement('section');awards.className='about-awards reveal';awards.innerHTML='<div class="section-title">Визнання</div><div><h2>Результат, який<br><em>має підтвердження.</em></h2><p>Від якості виробничих процесів до присутності на міжнародних подіях — ці відзнаки фіксують роботу команди UNIKS.</p><div class="awards-grid"><article><div class="award-image"><img src="assets/uniks-iso-9001.jpg" alt="Сертифікат ISO 9001:2015 UNIKS"></div><h3>ISO 9001:2015</h3><span>Система управління якістю</span></article><article><div class="award-image"><img src="assets/uniks-beauty-expo-2025.jpg" alt="Диплом Central Asia Beauty Expo 2025"></div><h3>Beauty Expo 2025</h3><span>Участь у міжнародній виставці</span></article><article><div class="award-image"><img src="assets/uniks-made-in-ukraine-2025.jpg" alt="Нагорода Made in Ukraine 2025"></div><h3>Made in Ukraine 2025</h3><span>Партнер року в роздрібній торгівлі</span></article><article><div class="award-image"><img src="assets/uniks-social-2025.jpg" alt="Диплом Соціально відповідальний бізнес 2025"></div><h3>Соціально відповідальний бізнес</h3><span>Відзнака 2025 року</span></article></div></div>';document.querySelector('.band')?.before(awards);o.observe(awards)}
