if(document.body.dataset.page==='brands'){document.querySelector('.brand-showcase')?.remove();const brandRows=[{name:'Milky Dream',label:'Skin care',tag:'Care that feels like a ritual',text:'Лінійка догляду, побудована навколо молочних протеїнів: м’які формули, знайомі ритуали та відчуття турботи для шкіри й волосся.',tone:'#efd1df',products:[['Шампунь-кондиціонер «Основний догляд»','https://www.uniks.com.ua/wp-content/uploads/2024/04/9-1-500x667.jpg.webp'],['Шампунь-еліксир «STOP випадання»','https://www.uniks.com.ua/wp-content/uploads/2024/04/9-1-500x667.jpg.webp'],['Делікатний догляд для всієї родини','https://www.uniks.com.ua/wp-content/uploads/2024/04/9-1-500x667.jpg.webp']]},{name:'Be Trendy',label:'Color & mood',tag:'Express yourself',text:'Преміальний beauty-бренд про колір, настрій і текстури. Rich Vibes перетворює щоденний догляд на маленький виразний ритуал.',tone:'#dca0b8',products:[['Парфум Very Rich · Rich Vibes','https://www.uniks.com.ua/wp-content/uploads/2026/06/4820205305290-500x500.png.webp'],['Скраб з шимером · Rich Vibes','https://www.uniks.com.ua/wp-content/uploads/2026/06/4820205305221-500x500.png.webp'],['Бісер для ванни · Rich Vibes','https://www.uniks.com.ua/wp-content/uploads/2026/06/4820205305245-500x500.png.webp']]},{name:'Nature Code',label:'Natural care',tag:'Closer to nature',text:'Природні компоненти, аромати та домашні SPA-ритуали. Nature Code створений для уважного щоденного контакту з собою.',tone:'#b9cfa8',products:[['Кокосова олія з апельсином','https://www.uniks.com.ua/wp-content/uploads/2024/04/18-500x667.jpg.webp'],['Мило-олія «Чиста свідомість»','https://www.uniks.com.ua/wp-content/uploads/2021/11/xchysta-svidomist-kopiya-500x500.png.webp.pagespeed.ic.c18FAg7yC4.webp'],['Природний догляд для тіла','https://www.uniks.com.ua/wp-content/uploads/2024/04/18-500x667.jpg.webp']]},{name:'Біла овечка',label:'Family care',tag:'Softness for every day',text:'Зрозумілі засоби для дому, речей і щоденного комфорту родини: коли практичність, м’якість і турбота працюють разом.',tone:'#b9d9ed',products:[['Господарське рідке мило','assets/white-sheep-logo.jpg'],['Засоби для прання','assets/white-sheep-logo.jpg'],['Догляд за домом','assets/white-sheep-logo.jpg']]}];const rows=brandRows.map((b,i)=>{const cards=b.products.map(x=>`<article class="brand-product-card" style="--tone:${b.tone}"><div><img src="${x[1]}" alt="${x[0]}" loading="lazy"></div><span>${b.name}</span><h3>${x[0]}</h3></article>`).join('');return `<section class="brand-row" style="--brand-tone:${b.tone}"><div class="brand-row-copy"><span>${String(i+1).padStart(2,'0')} / ${b.label}</span><h2>${b.name}</h2><strong>${b.tag}</strong><p>${b.text}</p></div><div class="brand-row-carousel"><div class="brand-row-track">${cards}${cards}</div></div></section>`}).join('');const showcase=document.createElement('section');showcase.className='brand-rows reveal show';showcase.innerHTML=`<div class="section-title">Бренди UNIKS</div><h2>Від позиціонування<br>до <em>полиці.</em></h2><p class="brand-rows-lead">Кожен бренд має власний характер, аудиторію та сценарій використання. Нижче — продукти, у яких це стає відчутним.</p>${rows}`;document.querySelector('.band')?.before(showcase);document.head.insertAdjacentHTML('beforeend','<style>.brand-rows{background:#fbf8fc}.brand-rows>h2{margin:0;font-size:clamp(38px,4.4vw,66px);line-height:.93}.brand-rows>h2 em{color:#7a4d91}.brand-rows-lead{max-width:620px;margin:20px 0 75px;color:#5f5265;font-size:16px;line-height:1.75}.brand-row{display:grid;grid-template-columns:minmax(240px,.75fr) minmax(0,1.5fr);gap:48px;padding:50px 0;border-top:1px solid color-mix(in srgb,var(--brand-tone),#4b354f 25%)}.brand-row-copy>span,.brand-product-card span{font:10px/1.2 \'DM Mono\';letter-spacing:.12em;text-transform:uppercase}.brand-row-copy h2{margin:25px 0 8px;font-size:clamp(34px,3.4vw,52px);line-height:.9}.brand-row-copy strong{display:block;font:italic 25px/1.05 Cormorant Garamond,serif}.brand-row-copy p{margin:25px 0 0;font-size:15px;line-height:1.65;color:#5f5265}.brand-row-carousel{overflow:hidden;padding:5px}.brand-row-track{display:flex;width:max-content;gap:12px;animation:brand-row-move 28s linear infinite}.brand-row:hover .brand-row-track{animation-play-state:paused}.brand-product-card{width:205px;min-height:295px;padding:12px;background:#fff;box-shadow:0 8px 23px rgba(50,31,59,.1)}.brand-product-card>div{height:188px;display:grid;place-items:center;background:var(--tone);overflow:hidden}.brand-product-card img{width:100%;height:100%;object-fit:contain;padding:8px;transition:transform .3s}.brand-product-card:hover img{transform:scale(1.05)}.brand-product-card span{display:block;margin-top:14px;color:#80688d}.brand-product-card h3{margin:7px 0 0;font-size:16px;line-height:1.07;letter-spacing:-.035em}@keyframes brand-row-move{to{transform:translateX(calc(-50% - 6px))}}@media(max-width:800px){.brand-rows-lead{margin-bottom:45px}.brand-row{grid-template-columns:1fr;gap:25px;padding:38px 0}.brand-product-card{width:185px;min-height:275px}.brand-product-card>div{height:170px}.brand-row-track{animation-duration:22s}}</style>');o.observe(showcase)}
