if(document.body.dataset.page==='brands'){document.querySelector('.band')?.remove();const rows=[...document.querySelectorAll('.brand-row')];const slogans=['Корисна молочна серія','Ваш стиль — бути різною, бути собою','Здоровий баланс природи та науки','Безпечні та ефективні засоби для дому та прання'];rows.forEach((row,i)=>{const tag=row.querySelector('strong');if(tag)tag.textContent=slogans[i]||''});const assortment=[[['Крем інтенсивно зволожуючий SOFT, 250 мл','https://www.uniks.com.ua/wp-content/uploads/2026/01/4820205304842_1-500x500.png.webp'],['Сироватка COLLAGEN, 30 мл','https://www.uniks.com.ua/wp-content/uploads/2025/11/sollagen-1-500x500.jpg.webp'],['Пінка для вмивання GLYCOLIC, 200 мл','https://www.uniks.com.ua/wp-content/uploads/2025/12/2-kopiya-2-500x500.png.webp']],[['Парфум Very Rich · Rich Vibes','https://www.uniks.com.ua/wp-content/uploads/2026/06/4820205305290-500x500.png.webp'],['Скраб з шимером · Rich Vibes','https://www.uniks.com.ua/wp-content/uploads/2026/06/4820205305221-500x500.png.webp'],['Бісер для ванни · Rich Vibes','https://www.uniks.com.ua/wp-content/uploads/2026/06/4820205305245-500x500.png.webp']],[['Кокосова олія з апельсином, 140 мл','https://www.uniks.com.ua/wp-content/uploads/2024/04/18-500x667.jpg.webp'],['Мило-олія «Чиста свідомість», 500 мл','https://www.uniks.com.ua/wp-content/uploads/2021/11/xchysta-svidomist-kopiya-500x500.png.webp.pagespeed.ic.c18FAg7yC4.webp'],['Кокосова олія з лемонграсом, 140 мл','https://www.uniks.com.ua/wp-content/uploads/2024/04/18-500x667.jpg.webp']]];rows.slice(0,3).forEach((row,i)=>[...row.querySelectorAll('.brand-product-card')].forEach((card,n)=>{const item=assortment[i][n%3];const img=card.querySelector('img'),title=card.querySelector('h3');if(img){img.src=item[1];img.alt=item[0]}if(title)title.textContent=item[0]}))}
if(document.body.dataset.page==='brands'){const rows=[...document.querySelectorAll('.brand-row')],logos=['data:image/jpeg;base64,','data:image/jpeg;base64,','assets/nature-code-logo.jpg','assets/white-sheep-logo.jpg'];rows.forEach((row,i)=>{const h=row.querySelector('.brand-row-copy h2');if(h){h.className='brand-logo';h.innerHTML='<img src="'+logos[i]+'" alt="'+(h.textContent||'Логотип бренду')+'">'}const label=row.querySelector('.brand-row-copy>span');if(i===0&&label)label.textContent='01 / Skin & body care';if(i===0)row.classList.add('milky-row')});document.head.insertAdjacentHTML('beforeend','<style>.brand-row-copy h2.brand-logo{height:76px;margin:20px 0 14px;display:flex;align-items:center}.brand-row-copy h2.brand-logo img{display:block;max-width:210px;max-height:76px;width:auto;height:auto;object-fit:contain;object-position:left center}.milky-row .brand-product-card{border:2px solid #e8acc7;box-shadow:0 10px 24px rgba(203,115,158,.16)}.milky-row .brand-product-card>div{background:#f7dce8}.milky-row .brand-product-card span{color:#b45c87}</style>')}
